start.example:
variables:
  targets: { type: json, required: true }
  mount:   { type: string, default: "/" }

ai-analyze.example:
instructions: Find mounts above the threshold
input: ${nodes.check.output}
outputMode: json
jsonSchema: {"type":"object","properties":{"verdict":{"type":"string"}}}
# invalid JSON triggers one repair retry

approval.example:
title: Approve restart of {{SERVICE}}
timeoutSec: 3600
onTimeout: reject

classifier.example:
input: ${nodes.check.output}
classes:
  - { name: disk, description: Disk / capacity / mount issues }
  - { name: network, description: Network / port / connectivity }
instructions: Classify the input into exactly one class.

